public static byte convertHexDigit(byte b) {
    // Convert an ASCII hex digit (0-9, a-f, A-F) to its numeric value (0-15).
    // Throw IllegalArgumentException if the character is not a valid hex digit.
    int value = b & 0xFF; // Treat byte as unsigned for comparison.
    if (value >= '0' && value <= '9') {
        return (byte) (value - '0');
    }
    if (value >= 'a' && value <= 'f') {
        return (byte) (value - 'a' + 10);
    }
    if (value >= 'A' && value <= 'F') {
        return (byte) (value - 'A' + 10);
    }
    throw new IllegalArgumentException("Invalid hex digit: " + (char) value);
}

